function resolveFfmpegBinary() {
  const envBinary = String(process.env.FFMPEG_BINARY || "").trim();
  if (envBinary) {
    return envBinary;
  }
  const bundledBinary = String(ffmpegInstaller?.path || "").trim();
  if (bundledBinary && existsSync(bundledBinary)) {
    return bundledBinary;
  }
  return "ffmpeg";
}

function resolveFfprobeBinary() {
  const envBinary = String(process.env.FFPROBE_BINARY || "").trim();
  if (envBinary) {
    return envBinary;
  }
  const bundledBinary = String(ffprobeStatic?.path || "").trim();
  if (bundledBinary && existsSync(bundledBinary)) {
    return bundledBinary;
  }
  return "ffprobe";
}

