  private async markTaskRunning(taskId: string) {
    if (await this.isTaskCancelled(taskId)) {
      return;
    }

    if (await this.prismaService.canUseDatabase()) {
      await this.prismaService.task.update({
        where: { id: taskId },
        data: {
          taskStatus: TaskStatus.RUNNING,
          startedAt: new Date(),
          errorMessage: null,
        },
      });
      return;
    }

    const task = database.tasks.find((item) => item.id === taskId);
    if (task) {
      task.taskStatus = "RUNNING";
      task.startedAt = new Date().toISOString();
      task.updatedAt = new Date().toISOString();
    }
  }

  private async updateTaskRunningOutput(
    taskId: string,
    outputJson: Record<string, unknown>,
    options?: { modelName?: string },
  ) {
    if (await this.isTaskCancelled(taskId)) {
      return;
    }

    if (await this.prismaService.canUseDatabase()) {
      await this.prismaService.task.update({
        where: { id: taskId },
        data: {
          taskStatus: TaskStatus.RUNNING,
          outputJson: outputJson as Prisma.InputJsonValue,
          ...(options?.modelName ? { modelName: options.modelName } : {}),
        },
      });
      return;
    }

    const task = database.tasks.find((item) => item.id === taskId);
    if (task) {
      task.taskStatus = "RUNNING";
      task.outputJson = outputJson;
      if (options?.modelName) {
        task.modelName = options.modelName;
      }
      task.updatedAt = new Date().toISOString();
    }
  }

  private async markTaskSuccess(
    taskId: string,
    outputJson: Record<string, unknown>,
    options?: { modelName?: string },
  ) {
    if (await this.isTaskCancelled(taskId)) {
      return;
    }

    if (await this.prismaService.canUseDatabase()) {
      await this.prismaService.task.update({
        where: { id: taskId },
        data: {
          taskStatus: TaskStatus.SUCCESS,
          finishedAt: new Date(),
          errorMessage: null,
          outputJson: outputJson as Prisma.InputJsonValue,
          ...(options?.modelName ? { modelName: options.modelName } : {}),
        },
      });
      return;
    }

    const task = database.tasks.find((item) => item.id === taskId);
    if (task) {
      task.taskStatus = "SUCCESS";
      task.finishedAt = new Date().toISOString();
      task.outputJson = outputJson;
      if (options?.modelName) {
        task.modelName = options.modelName;
      }
      task.updatedAt = new Date().toISOString();
    }
  }

  private async markTaskFailed(
    taskId: string,
    errorMessage: string,
    options?: {
      modelName?: string;
      outputJson?: Record<string, unknown>;
    },
  ) {
    if (await this.isTaskCancelled(taskId)) {
      return;
    }

    if (await this.prismaService.canUseDatabase()) {
      await this.prismaService.task.update({
        where: { id: taskId },
        data: {
          taskStatus: TaskStatus.FAILED,
          finishedAt: new Date(),
          errorMessage,
          ...(options?.outputJson ? { outputJson: options.outputJson as Prisma.InputJsonValue } : {}),
          ...(options?.modelName ? { modelName: options.modelName } : {}),
        },
      });
      return;
    }

    const task = database.tasks.find((item) => item.id === taskId);
    if (task) {
      task.taskStatus = "FAILED";
      task.errorMessage = errorMessage;
      task.finishedAt = new Date().toISOString();
      if (options?.outputJson) {
        task.outputJson = options.outputJson;
      }
      if (options?.modelName) {
        task.modelName = options.modelName;
      }
      task.updatedAt = new Date().toISOString();
    }
  }

