  private normalizeWechatHtmlStyleConfig(
    value: unknown,
    fallback?: Partial<WechatHtmlStyleConfig>,
  ): WechatHtmlStyleConfig {
    const defaults = {
      ...buildDefaultWechatHtmlStyleConfig(),
      ...(fallback || {}),
    };
    const record = this.asRecord(value);
    const styleType = String(record?.styleType || "").trim();
    return {
      styleType: (
        ["general", "minimal", "space", "notice"].includes(styleType)
          ? styleType
          : defaults.styleType
      ) as WechatHtmlStyleType,
    };
  }

