  private normalizeDigitalHumanScriptTemplateCategory(value?: string) {
    const normalized = String(value || "").trim().toLowerCase();
    if (!normalized) {
      return "general";
    }
    switch (normalized) {
      case "brand_promo":
      case "activity_promo":
      case "knowledge":
      case "live_warmup":
      case "selling":
      case "general":
        return normalized;
      default:
        return "general";
    }
  }

  private normalizeDigitalHumanScriptTemplateNote(value?: string) {
    return String(value || "").trim().slice(0, 200);
  }

  private mapDigitalHumanScriptTemplateRow(item: {
    id?: string;
    userId?: string;
    name?: string;
    content?: string;
    note?: string;
    isShared?: boolean;
    category?: string;
    isArchived?: boolean;
    createdAt?: Date | string;
    updatedAt?: Date | string;
  }, currentUserId?: string): DouyinDigitalHumanScriptTemplateRecord {
    const ownerUserId = String(item.userId || "").trim();
    return {
      id: String(item.id || "").trim(),
      name: String(item.name || "").trim() || "我的数字人脚本模板",
      content: String(item.content || ""),
      note: this.normalizeDigitalHumanScriptTemplateNote(item.note),
      isShared: Boolean(item.isShared),
      category: this.normalizeDigitalHumanScriptTemplateCategory(item.category),
      isArchived: Boolean(item.isArchived),
      editable: !currentUserId || ownerUserId === currentUserId,
      createdAt: normalizeMaybeDate(item.createdAt) || new Date().toISOString(),
      updatedAt: normalizeMaybeDate(item.updatedAt) || new Date().toISOString(),
    };
  }

